def highlighted(source):
    lines=source.splitlines(keepends=True)
    offsets=[0]
    for line in lines: offsets.append(offsets[-1]+len(line))
    position=0; pieces=[]
    try:
        for tok in tokenize.generate_tokens(io.StringIO(source).readline):
            start=offsets[tok.start[0]-1]+tok.start[1]
            end=offsets[tok.end[0]-1]+tok.end[1]
            if end<=position: continue
            pieces.append(html.escape(source[position:start]))
            cls='kw' if tok.type==tokenize.NAME and keyword.iskeyword(tok.string) else {tokenize.STRING:'str',tokenize.COMMENT:'com',tokenize.NUMBER:'num'}.get(tok.type)
            escaped=html.escape(source[start:end])
            pieces.append(f'<span class="{cls}">{escaped}</span>' if cls else escaped)
            position=end
        pieces.append(html.escape(source[position:]))
        return ''.join(pieces)
    except (tokenize.TokenError,IndexError):
        return html.escape(source)


def source_sections(assets):
    descriptions={'sampling.py':'Exact ordered-pair proposals and simple-graph rejection.',
      'union_find.py':'Path compression, union by size, component edge counts and persistent event validation.',
      'experiments.py':'Compiled snapshot and full-trajectory trials with parallel batches.',
      'statistics.py':'Theoretical constants and Wilson binomial intervals.',
      'export.py':'Atomic checkpointing and machine-readable aggregate exports.',
      'run.py':'Configurable CLI, independent trial seeds, collision checks and resume.',
      'test_simulation.py':'Independent adjacency traversal, constructed histories, distribution and export tests.',
      'build_page.py':'This static article builder: tables, charts and embedded actual source.',
      'validate_page.py':'Static paths, embedded data and source consistency checks.',
      'giant_component_simulation1.py':'Legacy snapshot experiment. Preserved unchanged; not used for the new results.',
      'giant_component_simulation2.py':'Legacy at-most-one-complex snapshot experiment (0.9957). It is not Theorem 15.',
      'giant_component_evolution_n100.py':'Legacy NetworkX animation generator; preserved unchanged.',
      'giant_component_evolution_n100_4graphs.py':'Legacy four-graph animation generator; preserved unchanged.',
      'giant_component_evolution_n100_4graphs_stage2.py':'Legacy stage-two animation generator; preserved unchanged.'}
    chunks=[]
    for i,path in enumerate(sorted(assets.rglob('*.py'))):
        source=path.read_text(encoding='utf8')
        rel=path.relative_to(assets).as_posix(); codeid=f'source-{i}'
        if '__pycache__' in rel: continue
        description=descriptions.get(path.name,'Package marker for module-based execution.')
        chunks.append(f'<details class="script" data-source="{rel}" data-sha256="{hashlib.sha256(source.encode()).hexdigest()}"><summary>{html.escape(rel)}</summary><p>{description}</p><div class="scriptbar"><a href="{ASSET+rel}" download>Download actual Python file</a><button class="copy" data-code="{codeid}" type="button">Copy code</button></div><pre class="source-code"><code id="{codeid}">{highlighted(source)}</code></pre></details>')
    return '\n'.join(chunks)


def table(rows,experiment):
    selected=[r for r in rows if r['experiment']==experiment]
    by={(r['n'],r['model']):r for r in selected}
    output='<div class="table-wrap"><table><caption>Empirical '+experiment+' probabilities · 95% Wilson intervals for finite-n p</caption><thead><tr><th rowspan="2">n</th><th colspan="4">Simple graph</th><th colspan="4">Multigraph</th></tr><tr>'+('<th>Successes / R</th><th>Estimate</th><th>Signed Δ</th><th>95% CI</th>'*2)+'</tr></thead><tbody>'
    for n in NS:
        output+=f'<tr><td>{n:,}</td>'
        for model in ['simple','multigraph']:
            r=by[(n,model)]
            output+=f'<td>{r["successes"]} / {r["trials"]}</td><td>{r["probability"]:.4f}</td><td>{r["signed_difference"]:+.4f}</td><td>[{r["ci_low"]:.4f}, {r["ci_high"]:.4f}]</td>'
        output+='</tr>'
    return output+'</tbody></table></div>'


def chart(rows,experiment):
    selected=[r for r in rows if r['experiment']==experiment]
    # Constant limits are independently calculated, never rounded to 0.9325.
    limit=LIMITS[experiment]; w,h=920,340; x0,y0=68,28; width,height=815,250
    bottom=.78 if experiment=='trajectory' else .85
    x=lambda n:x0+width*(math.log10(n)-math.log10(50))/(5-math.log10(50))
    y=lambda p:y0+height*(1.01-p)/(1.01-bottom)
    svg=f'<div class="chart-wrap"><svg class="chart" viewBox="0 0 {w} {h}" role="img" aria-labelledby="chart-{experiment}-title chart-{experiment}-desc"><title id="chart-{experiment}-title">Monte Carlo estimates of the {experiment} event</title><desc id="chart-{experiment}-desc">Logarithmic vertex-count axis; points show proportions and vertical whiskers show Wilson 95 percent intervals. Exact values are in the following table. The dashed line is the asymptotic limit.</desc>'
    ticks=[.8,.85,.9,.95,1] if experiment=='trajectory' else [.85,.9,.95,1]
    for p in ticks:
        svg+=f'<path d="M{x0} {y(p):.2f}H{x0+width}" stroke="#dce2d4"/><text x="56" y="{y(p)+5:.2f}" text-anchor="end" font-size="12" fill="#4d6258">{p:.2f}</text>'
    for n in [50,100,1000,10000,100000]:
        svg+=f'<text x="{x(n):.2f}" y="300" text-anchor="middle" font-size="12" fill="#4d6258">{n:,}</text>'
    svg+=f'<path d="M{x0} {y(limit):.2f}H{x0+width}" stroke="#5c675a" stroke-dasharray="7 5"/><text x="{x0+width}" y="{y(limit)-9:.2f}" text-anchor="end" font-size="12" fill="#344c41">Limit {limit:.7f}</text>'
    for model,col,offset in [('simple','#24597f',-2),('multigraph','#9c3d78',2)]:
        model_rows=sorted((r for r in selected if r['model']==model),key=lambda r:r['n'])
        pts=' '.join(f'{x(r["n"])+offset:.2f},{y(r["probability"]):.2f}' for r in model_rows)
        svg+=f'<polyline points="{pts}" fill="none" stroke="{col}" stroke-width="1.5" opacity=".65"/>'
        for r in model_rows:
            xx=x(r['n'])+offset; lo=y(r['ci_low']);hi=y(r['ci_high']); yy=y(r['probability'])
            svg+=f'<g stroke="{col}" fill="{col}"><title>{model}, n={r["n"]}: {r["successes"]}/{r["trials"]}, CI [{r["ci_low"]:.6f}, {r["ci_high"]:.6f}]</title><path d="M{xx:.2f} {lo:.2f}V{hi:.2f}M{xx-4:.2f} {lo:.2f}H{xx+4:.2f}M{xx-4:.2f} {hi:.2f}H{xx+4:.2f}" fill="none"/><circle cx="{xx:.2f}" cy="{yy:.2f}" r="3.5"/></g>'
    svg+='<text x="475" y="332" text-anchor="middle" font-size="13" fill="#344c41">Number of vertices n · logarithmic scale</text><text x="16" y="155" transform="rotate(-90 16 155)" text-anchor="middle" font-size="13" fill="#344c41">Event probability</text></svg><div class="chart-legend"><span class="simple">● Simple graph</span><span class="multigraph">● Multigraph</span><span>┄ Asymptotic limit</span></div></div>'
    return svg


