def build(assets,output):
    data=json.loads((assets/'data/results.json').read_text(encoding='utf8'))
    if not data['metadata'].get('complete') or len(data['rows'])!=60:
        raise ValueError('Require complete coverage of both models, both events and 15 sizes')
    for row in data['rows']:
        assert row['probability']==row['successes']/row['trials']
        assert (row['ci_low'],row['ci_high'])==wilson(row['successes'],row['trials'])
        assert row['theoretical_limit']==LIMITS[row['experiment']]
    runtime=sum(r['runtime_seconds'] for r in data['rows'])
    text=ARTICLE
    for exp in ['snapshot','trajectory']:
        text=text.replace('@@'+exp.upper()+'_CHART@@',chart(data['rows'],exp))
        text=text.replace('@@'+exp.upper()+'_TABLE@@',table(data['rows'],exp))
    text=text.replace('@@RUNTIME@@',f'Total measured batch runtime: {runtime:.1f} seconds ({runtime/60:.1f} minutes).')
    text=text.replace('@@RUNTIME_DETAIL@@',f'The longest cell took {max(r["runtime_seconds"] for r in data["rows"]):.1f} seconds on this run.')
    assert not re.search(r'@@[A-Z_]+@@',text.replace('@@SOURCES@@','').replace('@@DATA@@',''))
    text=text.replace('@@DATA@@',json.dumps(data,separators=(',',':')).replace('</','<\\/'))
    # Insert source last: builder source itself contains literal template tokens.
    text=text.replace('@@SOURCES@@',source_sections(assets))
    output.write_text(text,encoding='utf8')


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--assets',type=Path,default=Path(__file__).resolve().parents[1])
    p.add_argument('--output',type=Path)
    a=p.parse_args(); assets=a.assets.resolve()
    build(assets,a.output or assets.parent/'giant-components.html')


if __name__=='__main__':
    main()
